// Ported from test/web-utils.test.js (V1 utils.js): every case kept, now against the V2 callAction(ims, …).
// config.json is generated by `aio app build` and gitignored, so it is a virtual mock here.
import { callAction, newestFirst } from '#web/utils.ts'

jest.mock('../../src/commerce-backend-ui-2/web-src/src/config.json', () => ({
  'StuckOrders/list-alerts': 'http://x'
}), { virtual: true })

function reply (status: number, body: string) {
  return { ok: status >= 200 && status < 300, status, text: async () => body }
}

const ims = { imsToken: 't', imsOrgId: 'o' }
let fetchMock: jest.Mock

beforeEach(() => {
  fetchMock = jest.fn()
  global.fetch = fetchMock as unknown as typeof fetch
})

describe('callAction', () => {
  test('reads the action URL from ./config.json; an unknown action throws before any request', async () => {
    await expect(callAction(ims, 'StuckOrders/nope')).rejects.toThrow('No URL for StuckOrders/nope in config.json')
    expect(fetchMock).not.toHaveBeenCalled()
  })

  test('200 JSON returns the data and sends the IMS headers', async () => {
    fetchMock.mockResolvedValue(reply(200, '[{"order":"1"}]'))
    const data = await callAction(ims, 'StuckOrders/list-alerts', { a: 1 })
    expect(data).toEqual([{ order: '1' }])
    const [url, opts] = fetchMock.mock.calls[0]
    expect(url).toBe('http://x')
    expect(opts.method).toBe('POST')
    expect(opts.headers.Authorization).toBe('Bearer t')
    expect(opts.headers['x-gw-ims-org-id']).toBe('o')
    expect(opts.body).toBe('{"a":1}')
  })

  test('401 JSON error throws the error text', async () => {
    fetchMock.mockResolvedValue(reply(401, '{"error":"x"}'))
    await expect(callAction(ims, 'StuckOrders/list-alerts')).rejects.toThrow('x')
  })

  test('502 HTML throws the HTTP status', async () => {
    fetchMock.mockResolvedValue(reply(502, '<!DOCTYPE html><html></html>'))
    await expect(callAction(ims, 'StuckOrders/list-alerts')).rejects.toThrow('HTTP 502')
  })

  test('502 with an empty body throws the HTTP status', async () => {
    fetchMock.mockResolvedValue(reply(502, ''))
    await expect(callAction(ims, 'StuckOrders/list-alerts')).rejects.toThrow('HTTP 502')
  })

  test('200 HTML throws that the response is not JSON', async () => {
    fetchMock.mockResolvedValue(reply(200, '<html></html>'))
    await expect(callAction(ims, 'StuckOrders/list-alerts')).rejects.toThrow('HTTP 200: response is not JSON')
  })
})

describe('newestFirst', () => {
  test('sorts by at, newest first, without changing the input', () => {
    const rows = [{ order: 'a', at: '2027-01-01T00:00:00.000Z' }, { order: 'b', at: '2027-01-03T00:00:00.000Z' }, { order: 'c', at: '2027-01-02T00:00:00.000Z' }]
    expect(newestFirst(rows).map(r => r.order)).toEqual(['b', 'c', 'a'])
    expect(rows.map(r => r.order)).toEqual(['a', 'b', 'c'])
  })
})
